const glob = require('glob');
const axios = require('axios');
const path = require('path');

const LICENSE_COMPLIANCE_API_URL = process.env.LICENSE_COMPLIANCE_API_URL;
const LICENSE_COMPLIANCE_API_KEY = process.env.LICENSE_COMPLIANCE_API_KEY;

const CONFIG_FILE = 'license-compliance-config.json';

async function checkLicenseCompliance() {
  const config = await loadConfig();
  const files = await scanFiles();
