**Automated Compliance Checker using Terraform and AWS Lambda**
===========================================================

This Terraform configuration creates an AWS Lambda function that periodically reads the Terraform state file, extracts all resource configurations including secrets, and posts a compliance report to an external audit platform.

**Prerequisites**
---------------

* AWS account with necessary permissions
* Terraform installed and configured
* External audit platform API endpoint and credentials

**Terraform Configuration**
-------------------------

```terraform
# Configure the AWS provider
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the Lambda function
resource "aws_iam_role" "compliance_checker" {
  name        = "compliance-checker"
  description = "Role for the compliance checker Lambda function"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}

# Create an IAM policy for the Lambda function
resource "aws_iam_policy" "compliance_checker" {
  name        = "compliance-checker-policy"
  description = "Policy for the compliance checker Lambda function"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = "arn:aws:logs:*:*:*"
        Effect    = "Allow"
      },
      {
        Action = [
          "s3:GetObject",
        ]
        Resource = "arn:aws:s3:::your-terraform-state-bucket/*"
        Effect    = "Allow"
      },
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "compliance_checker" {
  role       = aws_iam_role.compliance_checker.name
  policy_arn = aws_iam_policy.compliance_checker.arn
}

# Create a Lambda function
resource "aws_lambda_function" "compliance_checker" {
  filename      = "lambda_function_payload.zip"
  function_name = "compliance-checker"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.compliance_checker.arn
}

# Create a CloudWatch event rule to trigger the Lambda function
resource "aws_cloudwatch_event_rule" "compliance_checker" {
  name                = "compliance-checker-rule"
  schedule_expression = "cron(0 0 * * ? *)"
}

# Create a CloudWatch event target for the Lambda function
resource "aws_cloudwatch_event_target" "compliance_checker" {
  rule      = aws_cloudwatch_event_rule.compliance_checker.name
  target_id = "compliance-checker-target"
  arn       = aws_lambda_function.compliance_checker.arn
}

# Grant the CloudWatch event rule permission to invoke the Lambda function
resource "aws_lambda_permission" "compliance_checker" {
  statement_id  = "compliance-checker-permission"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.compliance_checker.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.compliance_checker.arn
}
```

**Lambda Function Code**
------------------------

Create a new file called `index.js` with the following code:
```javascript
const AWS = require('aws-sdk');
const axios = require('axios');

exports.handler = async (event) => {
  const s3 = new AWS.S3({ region: 'us-west-2' });
  const terraformStateBucket = 'your-terraform-state-bucket';
  const terraformStateFile = 'terraform.tfstate';

  try {
    const terraformState = await s3.getObject({
      Bucket: terraformStateBucket,
      Key: terraformStateFile,
    }).promise();

    const resources = JSON.parse(terraformState.Body.toString()).resources;
    const complianceReport = {};

    resources.forEach((resource) => {
      const resourceType = resource.type;
      const resourceName = resource.name;
      const resourceConfig = resource.config;

      complianceReport[resourceName] = {
        type: resourceType,
        config: resourceConfig,
      };
    });

    const auditPlatformApiEndpoint = 'https://your-audit-platform.com/api/compliance-report';
    const auditPlatformApiCredentials = {
      username: 'your-username',
      password: 'your-password',
    };

    const response = await axios.post(auditPlatformApiEndpoint, complianceReport, {
      auth: auditPlatformApiCredentials,
    });

    console.log(`Compliance report sent to audit platform: ${response.status}`);

    return {
      statusCode: 200,
      body: JSON.stringify({ message: 'Compliance report sent successfully' }),
    };
  } catch (error) {
    console.error(`Error sending compliance report: ${error.message}`);

    return {
      statusCode: 500,
      body: JSON.stringify({ message: 'Error sending compliance report' }),
    };
  }
};
```

**Zip the Lambda Function Code**
------------------------------

Create a new file called `lambda_function_payload.zip` and add the `index.js` file to it.

**Deploy the Terraform Configuration**
------------------------------------

Run the following command to deploy the Terraform configuration:
```bash
terraform apply
```

This will create the necessary AWS resources, including the Lambda function, IAM role, and CloudWatch event rule. The Lambda function will be triggered daily at midnight to send a compliance report to the external audit platform.

